import XCTest
@testable import Remo

/// Builds the AI tool setup snippets and compares them with the ones the web
/// app produced (fixtures/mcp/client-examples.expected.json, regenerated by
/// apps/web mcp-clients.test.ts).
final class McpClientExamplesTests: XCTestCase {
    private struct Expected: Decodable {
        struct Example: Decodable {
            let name: String
            let location: String
            let snippet: String
        }
        let examples: [Example]
    }

    func testMatchesTheSnippetsEveryPlatformShows() throws {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("../../../../fixtures/mcp/client-examples.expected.json").standardized
        let expected = try JSONDecoder().decode(Expected.self, from: Data(contentsOf: url)).examples
        let actual = McpClientExamples.build(endpoint: "https://remo.example.test/api/mcp", token: "rm_" + String(repeating: "Ab1-_", count: 8) + "abc")
        XCTAssertEqual(actual.count, expected.count)
        for (example, item) in zip(actual, expected) {
            XCTAssertEqual(example.name, item.name)
            XCTAssertEqual(example.location, item.location)
            XCTAssertEqual(example.snippet, item.snippet, example.name)
        }
    }
}
